      struct BodyUniforms {
        worldMatrix : mat4x4<f32>,
        bodyPosition : vec3<f32>,
        bodyRadius : f32,
        rimColor : vec3<f32>,
        rimPower : f32,
        specStrength : f32,
      }
      struct FrameUniforms {
        viewProjection : mat4x4<f32>,
        cameraPosition : vec3<f32>,
        sunPosition : vec3<f32>,
        cameraRight : vec3<f32>,
        cameraUp : vec3<f32>,
        time : f32,
        aspect : f32,
        tanHalfFov : f32,
