348   /** Translucent swirling cloud layer for Earth (alpha only, white colour). */
349   generateEarthClouds() {
350     const random = TextureGen.mulberry32(90210);
351     const width = 1024, height = 512;
352     return TextureGen.paintPixels(width, height, (u, v) => {
353       const direction = TextureGen.sphereDirection(u, v);
354       const swirl = TextureGen.fbm3(direction[0] * 3.8 + 2.2, direction[1] * 3.8, direction[2] * 3.8, 3);
355       const clump = TextureGen.fbm3(direction[0] * 7.5 + 14.0, direction[1] * 7.5, direction[2] * 7.5, 4);
356       const mask = TextureGen.smooth(Math.min(Math.max(clump - 0.52, 0) * 2.6, 1)) * (0.55 + 0.45 * swirl);
357       const alpha = Math.min(255, mask * 235);
358       return [255, 255, 255, alpha];
359     }, random);
