362   /**
363    * Saturn ring: 1024x2 canvas sampled at (r/1, 0.5) by the ring shader.
364    * Real-ish structure: C, B, A rings, the Cassini division and a narrow F ring;
365    * alpha is the ring opacity.
366    */
367   generateSaturnRing() {
368     const width = 1024, height = 2;
369     const random = TextureGen.mulberry32(77777);
370     const canvas = document.createElement('canvas');
371     canvas.width = width;
372     canvas.height = height;
373     const context = canvas.getContext('2d');
374     const imageData = context.createImageData(width, height);
375     const pixels = imageData.data;
376     const gauss = (center, spread, peak) => peak * Math.exp(-Math.pow((width01 - center) / spread, 2));
377     for (let column = 0; column < width; column += 1) {
378       const r = column / (width - 1);
379       const noise = TextureGen.fbm3(r * 24.0, 0.37, 7.7, 3);
380       let alpha =
381         gauss(0.28, 0.10, 0.42) + gauss(0.52, 0.11, 0.85) + gauss(0.78, 0.062, 0.92)
382         + gauss(0.655, 0.014, 0.30) + gauss(0.905, 0.011, 0.42);
383       alpha *= 0.55 + 0.45 * noise;
384       /* Cassini division: a deep, sharp gap. */
385       const gap = TextureGen.smooth(Math.min(Math.max((r - 0.415) / 0.022, 0) * 1, 1))
386         * (1 - TextureGen.smooth(Math.min(Math.max((r - 0.500) / 0.028, 0) * 1, 1)));
387       alpha *= 1 - gap * 0.93;
388       const innerFade = TextureGen.smooth(Math.min(r / 0.05, 1));
389       const outerFade = 1 - TextureGen.smooth(Math.min(Math.max((r - 0.965) / 0.03, 0), 1));
390       const brightness = 0.78 + 0.22 * noise;
391       const red = Math.min(255, 238 * brightness * innerFade * outerFade + 12);
392       const green = Math.min(255, 228 * brightness * innerFade * outerFade + 10);
393       const blue = Math.min(255, 208 * brightness * innerFade * outerFade + 8);
394       for (let row = 0; row < height; row += 1) {
395         const index = (row * width + column) * 4;
396         pixels[index] = red;
397         pixels[index + 1] = green;
398         pixels[index + 2] = blue;
399         pixels[index + 3] = Math.min(255, alpha * 235 * innerFade * outerFade);
400       }
401     }
402     context.putImageData(imageData, 0, 0);
403     return canvas;
404   }
405 };

